=Correo: 
{{ $json.correo }}
Responde SOLO con un objeto JSON con estas claves: bl, contenedor, buque, puerto_origen, puerto_destino, etd, eta, incoterm. Sin texto adicional y sin bloques de codigo.

parameters.jsCode:
const t = String($json.text ?? $json.output ?? '');
const limpio = t.replace(/```json|```/gi, '').trim();

let datos;
try {
  datos = JSON.parse(limpio);
} catch (e) {
  datos = { error_parseo: true, bruto: t };
}
return { json: datos };

// Valores de las letras según ISO 6346 (se saltan los múltiplos de 11)
const LETRA = {A:10,B:12,C:13,D:14,E:15,F:16,G:17,H:18,I:19,J:20,K:21,L:23,
  M:24,N:25,O:26,P:27,Q:28,R:29,S:30,T:31,U:32,V:34,W:35,X:36,Y:37,Z:38};

function revisarContenedor(raw) {
  if (!raw) return null;
  const c = String(raw).toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (!/^[A-Z]{3}[UJZ][0-9]{7}$/.test(c)) return { c, ok: false };
  let suma = 0;
  for (let i = 0; i < 10; i++) {
    const v = i < 4 ? LETRA[c[i]] : Number(c[i]);
    suma += v * Math.pow(2, i);
  }
  const control = (suma % 11) % 10;
  return { c, ok: control === Number(c[10]) };
}

const ultimo = {};   // último estado conocido de cada BL
const salida = [];

for (const item of $input.all()) {
  const d = item.json.output ?? item.json;
  const r = revisarContenedor(d.contenedor);

  const previo = d.bl ? ultimo[d.bl] : null;
  let dias = null, alerta = '';
  if (previo && previo.eta && d.eta) {
    dias = Math.round((new Date(d.eta) - new Date(previo.eta)) / 86400000);
    if (dias > 2) alerta = `ETA retrasado ${dias} días`;
  }

  if (d.bl) {
    const nuevos = Object.fromEntries(
      Object.entries(d).filter(([k, v]) => v !== null && v !== '')
    );
    ultimo[d.bl] = { ...(previo || {}), ...nuevos };
  }

  salida.push({ json: {
    bl: d.bl, contenedor: r ? r.c : null, buque: d.buque,
    puerto_origen: d.puerto_origen, puerto_destino: d.puerto_destino,
    etd: d.etd, eta: d.eta, incoterm: d.incoterm,
    estado_contenedor: !r ? 'sin dato' : (r.ok ? 'OK' : 'REVISAR'),
    dias_demora: dias, alerta
  }});
}
return salida;
